import timezone from 'dayjs/plugin/timezone.js';
import utc from 'dayjs/plugin/utc.js';
import dayjs from 'dayjs';

export function dayjsInit() {
  dayjs.extend(utc);
  dayjs.extend(timezone);
}

export function utcToDetailed(utcTimeString: number | string): string {
  return dayjs(utcTimeString).format('YYYY-MM-DD HH:mm:ss');
}

export function utcToApproximate(utcTimeString: number): string {
  return dayjs(utcTimeString).format('MM-DD HH:mm');
}
